root = os.getcwd()
done_file = os.path.join(root, "tools", "applied.txt")
done = set(open(done_file).read().split()) if os.path.exists(done_file) else set()
tmp = tempfile.mkdtemp()
env = dict(os.environ, NOTCH=root, PLDIR=tmp)
for name, parts in PATCHES:
    path = os.path.join(tmp, name + ".py")
    with open(path, "wb") as f:
        f.write(base64.b64decode("".join(parts)))
    if name == "pl":
        continue
    if name in done:
        print("skipped  :", name, "(already in)")
        continue
    r = subprocess.run([sys.executable, path], env=env, capture_output=True, text=True)
    text = (r.stdout + r.stderr).strip()
    if r.returncode == 0:
        print("applied  :", name, text)
        done.add(name)
    elif "Already applied" in text:
        print("skipped  :", name, "(already in)")
        done.add(name)
    else:
        print("FAILED   :", name, text)
        sys.exit(1)
os.makedirs(os.path.dirname(done_file), exist_ok=True)
with open(done_file, "w") as f:
    f.write("\n".join(sorted(done)) + "\n")
print("patches done")
